#!/usr/bin/env python3
"""
Disease -> ranked genes -> functional enrichment, grounded in real APIs.

Recipe: map-disease-to-genes-and-pathways (sci-ai-enabler, evidence: Reported)
  1. Open Targets GraphQL API   -> disease name to EFO ID -> top-N targets by
                                    overall association score (ranked_genes.csv)
  2. gget enrichr (Enrichr API) -> GO/KEGG/Reactome/Hallmark/DisGeNET enrichment
                                    on that gene list (enrichment_results.csv)
  3. Positive-control check     -> original disease should resurface in the
                                    DisGeNET enrichment results
  4. provenance.json            -> versions, query, timestamp, input/output hashes

No gene set or pathway term is generated by an LLM. Every row in both output
CSVs traces to a specific API response captured on disk.

Usage:
    python analysis.py "type 2 diabetes" --n-genes 30
"""
import argparse
import csv
import hashlib
import json
import sys
import time
import urllib.request

OT_GRAPHQL_URL = "https://api.platform.opentargets.org/api/v4/graphql"

ENRICHR_LIBRARIES = [
    "GO_Biological_Process_2023",
    "KEGG_2021_Human",
    "Reactome_2022",
    "MSigDB_Hallmark_2020",
    "DisGeNET",
]

DISEASE_SEARCH_QUERY = """
query DiseaseSearch($q: String!) {
  search(queryString: $q, entityNames: ["disease"], page: {index: 0, size: 5}) {
    hits {
      id
      name
      entity
    }
  }
}
"""

DISEASE_TARGETS_QUERY = """
query DiseaseTargets($efoId: String!, $size: Int!) {
  disease(efoId: $efoId) {
    id
    name
    associatedTargets(page: {index: 0, size: $size}) {
      count
      rows {
        score
        target {
          id
          approvedSymbol
          approvedName
        }
        datatypeScores {
          id
          score
        }
      }
    }
  }
}
"""


def graphql(query: str, variables: dict) -> dict:
    body = json.dumps({"query": query, "variables": variables}).encode("utf-8")
    req = urllib.request.Request(
        OT_GRAPHQL_URL,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
    if "errors" in payload:
        raise RuntimeError(f"Open Targets GraphQL error: {payload['errors']}")
    return payload["data"]


def resolve_disease(name: str) -> dict:
    data = graphql(DISEASE_SEARCH_QUERY, {"q": name})
    hits = [h for h in data["search"]["hits"] if h["entity"] == "disease"]
    if not hits:
        raise SystemExit(f"No Open Targets disease match for '{name}'")
    best = hits[0]
    print(f"Resolved '{name}' -> {best['id']} ({best['name']})", file=sys.stderr)
    return best


def fetch_ranked_targets(efo_id: str, n: int) -> list:
    data = graphql(DISEASE_TARGETS_QUERY, {"efoId": efo_id, "size": n})
    rows = data["disease"]["associatedTargets"]["rows"]
    out = []
    for i, r in enumerate(rows, start=1):
        out.append(
            {
                "rank": i,
                "gene_symbol": r["target"]["approvedSymbol"],
                "ensembl_id": r["target"]["id"],
                "gene_name": r["target"]["approvedName"],
                "overall_association_score": round(r["score"], 4),
                "datatype_scores": json.dumps(
                    {d["id"]: round(d["score"], 4) for d in r["datatypeScores"]}
                ),
            }
        )
    return out


def write_csv(path: str, rows: list, fieldnames: list) -> str:
    with open(path, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=fieldnames)
        w.writeheader()
        w.writerows(rows)
    return sha256_file(path)


def sha256_file(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()


def run_enrichment(gene_symbols: list) -> list:
    """Run gget enrichr across ENRICHR_LIBRARIES, tag each hit with its library,
    keep only adjusted p < 0.05, return combined rows sorted by adj p-value."""
    import gget

    combined = []
    for lib in ENRICHR_LIBRARIES:
        try:
            df = gget.enrichr(gene_symbols, database=lib)
        except Exception as e:
            print(f"WARNING: enrichr call failed for {lib}: {e}", file=sys.stderr)
            continue
        if df is None or df.empty:
            continue
        df = df[df["adj_p_val"] < 0.05].copy()
        df["library"] = lib
        combined.append(df)

    if not combined:
        return []

    import pandas as pd

    result = pd.concat(combined, ignore_index=True)
    result = result.sort_values("adj_p_val")
    cols = [
        "library",
        "path_name",
        "overlapping_genes",
        "p_val",
        "adj_p_val",
        "combined_score",
    ]
    cols = [c for c in cols if c in result.columns]
    return result[cols].to_dict(orient="records")


def positive_control_check(disease_name: str, enrichment_rows: list) -> bool:
    tokens = [t.lower() for t in disease_name.split() if len(t) > 3]
    for row in enrichment_rows:
        if row.get("library") != "DisGeNET":
            continue
        term = str(row.get("path_name", "")).lower()
        if any(tok in term for tok in tokens):
            return True
    return False


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("disease", help="Disease name, e.g. 'type 2 diabetes'")
    ap.add_argument("--n-genes", type=int, default=30)
    ap.add_argument("--out-genes", default="ranked_genes.csv")
    ap.add_argument("--out-enrichment", default="enrichment_results.csv")
    ap.add_argument("--out-provenance", default="provenance.json")
    args = ap.parse_args()

    started = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

    disease = resolve_disease(args.disease)
    targets = fetch_ranked_targets(disease["id"], args.n_genes)
    if not targets:
        raise SystemExit(f"Open Targets returned zero associated targets for {disease['id']}")

    genes_hash = write_csv(
        args.out_genes,
        targets,
        ["rank", "gene_symbol", "ensembl_id", "gene_name", "overall_association_score", "datatype_scores"],
    )
    print(f"Wrote {args.out_genes} ({len(targets)} genes)", file=sys.stderr)

    gene_symbols = [t["gene_symbol"] for t in targets]
    enrichment_rows = run_enrichment(gene_symbols)
    if enrichment_rows:
        enrichment_hash = write_csv(
            args.out_enrichment,
            enrichment_rows,
            ["library", "path_name", "overlapping_genes", "p_val", "adj_p_val", "combined_score"],
        )
    else:
        enrichment_hash = None
        print("WARNING: no enrichment terms survived adj_p_val < 0.05", file=sys.stderr)

    control_passed = positive_control_check(args.disease, enrichment_rows)
    if not control_passed:
        print(
            f"WARNING: positive-control check FAILED — '{args.disease}' did not "
            "resurface in DisGeNET results. Check gene-symbol/species mapping "
            "before trusting the enrichment table.",
            file=sys.stderr,
        )
    else:
        print("Positive-control check passed: disease resurfaced in DisGeNET results.", file=sys.stderr)

    provenance = {
        "started_utc": started,
        "query": {"disease_input": args.disease, "n_genes_requested": args.n_genes},
        "resolved_disease": disease,
        "sources": {
            "open_targets_graphql": OT_GRAPHQL_URL,
            "enrichr_libraries": ENRICHR_LIBRARIES,
        },
        "outputs": {
            args.out_genes: genes_hash,
            args.out_enrichment: enrichment_hash,
        },
        "positive_control_passed": control_passed,
        "gget_version": _safe_version("gget"),
        "pandas_version": _safe_version("pandas"),
    }
    with open(args.out_provenance, "w") as f:
        json.dump(provenance, f, indent=2)
    print(f"Wrote {args.out_provenance}", file=sys.stderr)


def _safe_version(pkg: str) -> str:
    try:
        import importlib.metadata as md

        return md.version(pkg)
    except Exception:
        return "unknown"


if __name__ == "__main__":
    main()

